-- Generated by `make contracts` from contracts/cdc_nndss_weekly.odcs.yaml. Do not edit: change the contract and regenerate.
-- Business rules from the contract only: total rows, renamed labels, partial places, flag meanings,
-- then the conformed condition, place and time keys (conformedDimensions). Nothing is removed or
-- changed: each rule adds a column beside the published values.
with stg as (
    select * from {{ ref('stg_cdc_nndss_weekly') }}
),

ruled as (
    select
      stg.*,
      coalesce((location2 IS NOT NULL AND upper(location2) NOT IN ('NON-US RESIDENTS', 'NON-U.S. RESIDENTS')), false) AS "is_total_row",
      CASE regexp_replace(upper(trim("states")), '[.]', '', 'g') WHEN 'COMMONWEALTH OF NORTHERN MARIANA ISLANDS' THEN 'Northern Mariana Islands' WHEN 'NORTHERN MARIANA ISLANDS' THEN 'Northern Mariana Islands' ELSE "states" END AS "states_label",
      CASE WHEN "states" IS NULL THEN NULL ELSE CASE regexp_replace(upper(trim("states")), '[.]', '', 'g') WHEN 'NEW YORK' THEN 'New York State excluding New York City, which NNDSS reports as its own area; not the whole state GBD models' ELSE NULL END END AS "states_partial_note",
      CASE trim("m1_flag") WHEN '-' THEN 'no reported cases' WHEN 'U' THEN 'unavailable' WHEN 'N' THEN 'not reportable in this jurisdiction' WHEN 'NN' THEN 'not nationally notifiable' WHEN 'NP' THEN 'nationally notifiable but not published' WHEN 'NC' THEN 'not calculated' ELSE NULL END AS "m1_flag_meaning",
      CASE trim("m2_flag") WHEN '-' THEN 'no reported cases' WHEN 'U' THEN 'unavailable' WHEN 'N' THEN 'not reportable in this jurisdiction' WHEN 'NN' THEN 'not nationally notifiable' WHEN 'NP' THEN 'nationally notifiable but not published' WHEN 'NC' THEN 'not calculated' ELSE NULL END AS "m2_flag_meaning",
      CASE trim("m3_flag") WHEN '-' THEN 'no reported cases' WHEN 'U' THEN 'unavailable' WHEN 'N' THEN 'not reportable in this jurisdiction' WHEN 'NN' THEN 'not nationally notifiable' WHEN 'NP' THEN 'nationally notifiable but not published' WHEN 'NC' THEN 'not calculated' ELSE NULL END AS "m3_flag_meaning",
      CASE trim("m4_flag") WHEN '-' THEN 'no reported cases' WHEN 'U' THEN 'unavailable' WHEN 'N' THEN 'not reportable in this jurisdiction' WHEN 'NN' THEN 'not nationally notifiable' WHEN 'NP' THEN 'nationally notifiable but not published' WHEN 'NC' THEN 'not calculated' ELSE NULL END AS "m4_flag_meaning"
    from stg
),

keyed as (
    select
    ruled.*,
    ruled."states_label" AS "_p_label",
    CASE WHEN place_state.state_fips IS NULL THEN NULL ELSE 'US-' || place_state.state_fips END AS "_p_whole",
    CASE regexp_replace(upper(trim(ruled."states_label")), '[.]', '', 'g') WHEN 'US RESIDENTS' THEN 'USA' WHEN 'NORTHERN MARIANA ISLANDS' THEN 'US-69' WHEN 'US VIRGIN ISLANDS' THEN 'US-78' ELSE NULL END AS "_p_decl_key",
    CASE regexp_replace(upper(trim(ruled."states_label")), '[.]', '', 'g') WHEN 'NEW YORK CITY' THEN 'US-36' ELSE NULL END AS "_p_decl_parent",
    CASE regexp_replace(upper(trim(ruled."states_label")), '[.]', '', 'g') WHEN 'NEW YORK CITY' THEN 'New York City only, which NNDSS reports as its own area; part of New York State' ELSE NULL END AS "_p_decl_note",
    ruled."states_partial_note" AS "_p_note",
    try_cast(ruled."year" AS BIGINT) AS "_t_year",
    try_cast(ruled."week" AS BIGINT) AS "_t_week"
  from ruled
  left join {{ ref('stg_census_fips_state') }} as place_state
  on regexp_replace(upper(trim(ruled."states_label")), '[.]', '', 'g') = regexp_replace(upper(trim(place_state.state_name)), '[.]', '', 'g')
)

select
  keyed.* exclude ("_p_label", "_p_whole", "_p_decl_key", "_p_decl_parent", "_p_decl_note", "_p_note", "_t_year", "_t_week"),
  CAST(CASE WHEN keyed."label" IS NULL THEN NULL ELSE 'cdc_nndss_weekly:' || keyed."label" END AS VARCHAR) AS "condition_key",
  CAST(keyed."label" AS VARCHAR) AS "condition_label",
  CAST('unresolved: the weekly tables do not say whether a label counts confirmed, probable or both kinds of case' AS VARCHAR) AS "condition_case_status",
  CAST(CASE keyed."label" WHEN 'Candida auris, clinical' THEN 'clinical' WHEN 'Candida auris, screening' THEN 'screening' ELSE NULL END AS VARCHAR) AS "condition_case_subtype",
  CAST(CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_nndss_weekly:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END AS VARCHAR) AS "place_key",
  CAST(keyed._p_label AS VARCHAR) AS "place_label",
  CAST(CASE WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN coalesce(keyed._p_decl_parent, keyed._p_whole) ELSE NULL END AS VARCHAR) AS "place_parent_key",
  CAST(coalesce((keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)), false) AS BOOLEAN) AS "place_is_partial",
  CAST(CASE WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) AND coalesce(keyed._p_decl_parent, keyed._p_whole) IS NOT NULL THEN coalesce(keyed._p_decl_note, keyed._p_note) WHEN (CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_nndss_weekly:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END) IS NULL THEN 'unresolved: the contract does not declare this place label and it is not a name or code in the Census code files' ELSE NULL END AS VARCHAR) AS "place_note",
  CAST(CASE WHEN (CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/cdc_nndss_weekly:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END) IS NULL THEN 'unresolved' WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN 'partial_area' ELSE 'resolved' END AS VARCHAR) AS "place_status",
  CAST(keyed._t_year AS BIGINT) AS "mmwr_year",
  CAST(keyed._t_week AS BIGINT) AS "mmwr_week",
  CAST(CASE WHEN keyed._t_year IS NULL OR keyed._t_week IS NULL THEN NULL ELSE CAST(keyed._t_year AS VARCHAR) || '-W' || lpad(CAST(keyed._t_week AS VARCHAR), 2, '0') END AS VARCHAR) AS "time_key",
  CAST('mmwr_week' AS VARCHAR) AS "time_grain",
  CAST('the MMWR year and week the reporting jurisdiction assigns; which date it assigns by (onset, diagnosis, laboratory result or report) is not stated in the weekly tables' AS VARCHAR) AS "date_basis"
from keyed
